def deal(deck, n_players, cards_each):
    """Deal cards_each cards to every player from the top (end) of the deck.

    Dealt cards are removed from deck. Cards go round the table one at a time.
    """
    hands = [[]] * n_players
    for _ in range(cards_each):
        for p in range(n_players):
            hands[p].append(deck.pop())
    return hands

