import unittest
from cards import deal


class Regression(unittest.TestCase):
    def test_deck_is_consumed(self):
        deck = list(range(10))
        deal(deck, 2, 2)
        self.assertEqual(deck, [0, 1, 2, 3, 4, 5])

    def test_three_players(self):
        self.assertEqual(deal(list(range(9)), 3, 2), [[8, 5], [7, 4], [6, 3]])

    def test_hands_are_independent_lists(self):
        hands = deal(list(range(6)), 2, 1)
        hands[0].append("x")
        self.assertEqual(hands[1], [4])

    def test_empty_deck_raises(self):
        with self.assertRaises(IndexError):
            deal([], 2, 1)

